/* Authored C1 chamber/bottleneck phrases in persistent world coordinates. */
static float cavern_world(float y){return (ex.cavernWorldReady?ex.cavernWorldQ/(float)Q:ex.backgroundY/(float)Q)+y;}
static float cavern_phrase(float y,int channel){static const int widths[6][8]={{94,76,110,82,120,78,102,88},{100,80,118,86,124,78,110,90},{104,78,118,84,126,82,112,94},{108,84,122,92,126,88,114,96},{110,82,124,90,128,86,118,98},{96,76,112,84,116,78,106,90}},centres[8]={160,146,174,152,170,143,177,158};int k=journey_kind(),profile=k==ENV_ROOT?0:k==ENV_HIVE?1:k==ENV_CRYSTAL?3:k==ENV_ICE?4:k==ENV_BEAST?5:2;float world=cavern_world(y),node=floorf(world/512),t=world/512-node;t=t*t*(3-2*t);int a=((int)node+journey_number()*3+ex.section)%8;if(a<0)a+=8;int b=(a+1)%8;return channel?centres[a]+(centres[b]-centres[a])*t:widths[profile][a]+(widths[profile][b]-widths[profile][a])*t;}
static float cavern_island_radius(int y){if(ex.giant.active||(custom_environment()&&journey_kind()!=ENV_CRYSTAL))return 0;float w=fmodf(cavern_world(y),1024);if(w<0)w+=1024;float t=(w-256)/512;if(t<=0||t>=1)return 0;float r=18*sinf(t*3.14159265359f)*sinf(t*3.14159265359f),arena=ex.bossWarning?(100-ex.bossWarning)/100.0f:ex.bossSpawned?1:0;return r*(1-arena);}
